def build_program_application(*, release_store: ProgramReleaseStore | None=None, root: Path | None=None) -> ProgramApplicationService:
    """Compose the Program application from concrete domain stores."""
    program = UnifiedReleaseProgramStore(release_store=release_store, root=root)
    return ProgramApplicationService.from_components(program=program, operations=UnifiedReleaseProgramOperationsStore(program), handoff=UnifiedReleaseProgramHandoffStore(program), vault=UnifiedReleaseProgramVaultStore(program), vault_operations=UnifiedReleaseProgramVaultOperationsStore(program), continuity=UnifiedReleaseProgramContinuityStore(program), continuity_distribution=UnifiedReleaseProgramContinuityDistributionStore(program), continuity_acceptance=UnifiedReleaseProgramContinuityAcceptanceStore(program), continuity_acceptance_change=UnifiedReleaseProgramContinuityAcceptanceChangeStore(program), command_center=UnifiedReleaseProgramContinuityCommandCenterStore(program), command_center_signoff=UnifiedReleaseProgramContinuityCommandCenterSignoffStore(program), receiver_acceptance=UnifiedReleaseProgramContinuityCommandCenterAcceptanceStore(program), receiver_acceptance_change=UnifiedReleaseProgramContinuityCommandCenterAcceptanceChangeStore(program))
